    out = [row[:] for row in grid]

    # Fill gaps between matching non-background cells along rows and columns.
    colors = {v for row in grid for v in row if v != grid[0][0]}
    for color in colors:
        for r in range(h):
            cols = [c for c in range(w) if grid[r][c] == color]
            for a, b in zip(cols, cols[1:]):
                for c in range(a + 1, b):
                    if grid[r][c] != color:
                        out[r][c] = 3
        for c in range(w):
            rows = [r for r in range(h) if grid[r][c] == color]
            for a, b in zip(rows, rows[1:]):
                for r in range(a + 1, b):
                    if grid[r][c] != color:
                        out[r][c] = 3
