def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    for color in set(v for row in grid for v in row if v != background):
        for r in range(h):
            cols = [c for c in range(w) if grid[r][c] == color]
            for a, b in zip(cols, cols[1:]):
                for c in range(a + 1, b):
                    out[r][c] = 3
        for c in range(w):
            rows = [r for r in range(h) if grid[r][c] == color]
            for a, b in zip(rows, rows[1:]):
                for r in range(a + 1, b):
                    out[r][c] = 3

    return out
